    "text": "長 a 的唸法跟字母 A 的名稱一樣，KK 寫成 [e]。第一章提過，這個 [e] 跟注音ㄝ不一樣。美式發音會從 [e] 往 [ɪ] 滑過去，實際聽起來像 [eɪ]，很接近注音ㄟ。嘴巴的開口比短 a [æ] 小很多，下巴不用往下拉。"
