    "text": "長 a 有三種常見拼法。最多的是 a＋一個子音＋字尾不發音的 e，像 cake、name。這種拼法常簡寫成 a_e，底線代表中間那一個子音，後面幾課的 e_e、i_e、o_e、u_e 也是同樣的寫法。這個 e 本身不發音，它的工作是讓前面的 a 唸成長母音，所以 cap 加上 e 變成 cape，唸法就從 [kæp] 變成 [kep]。字中間常寫成 ai，像 rain、wait；在字尾則寫成 ay，像 day、play。有幾個常用字不照規則走：have 的 a 還是唸 [æ]，第二章學過；said、says 的母音唸 [ɛ]，跟 bed 一樣。a 或 ai 後面接 r 的時候唸法會變，像 care、hair，第七章再教；are 這個字唸 [ɑr]，也不照這課的規則。"
